sys_script_include.script:
var ServiceNow_School_Ajax = Class.create();
ServiceNow_School_Ajax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	findSubjectDate: function() {

        var dateInQuestion = this.getParameter('sysparm_trainning_date'),
			subjectInQuestion = this.getParameter('sysparm_class_subject');

        var grSchedule = new GlideRecord('x_1974925_servic_0_schedule');
        grSchedule.addQuery('trainning_date', dateInQuestion);
        grSchedule.addQuery('class_subject', subjectInQuestion);
        grSchedule.query();

		if(grSchedule.next()){
			return JSON.stringify({
				sys_id: grSchedule.getValue("sys_id"),
				number: grSchedule.getValue("number")
			});
		}
		return JSON.stringify({
			sys_id: null,
			number: null
		});
	},

    type: 'ServiceNow_School_Ajax'
});
